package com.example.lending.domain;

import com.example.lending.common.DateUtils;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    public static final int MAX_LOANS_PER_MEMBER = 5;
    public static final int LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;
    // 신용조회를 거치기 전에 만들어진 대출은 null 이다
    private final CreditCheck creditCheck;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                 CreditCheck creditCheck) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
        this.creditCheck = creditCheck;
    }

    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, DateUtils.addDays(loanedAt, LOAN_PERIOD_DAYS),
                null, Objects.requireNonNull(creditCheck, "creditCheck"));
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt, CreditCheck creditCheck) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    public void markReturned(LocalDate returnedAt) {
        if (this.returnedAt != null) {
            throw new LoanAlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    // 반납일이 기한 당일까지면 0일, 기한을 넘긴 날짜 수만큼 연체일이 된다
    public long overdueDays() {
        if (returnedAt == null) {
            throw new IllegalStateException("loan " + id + " is not returned yet");
        }
        return overdueDaysOf(dueAt, returnedAt);
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    // 반납 기록이 없는 대출의 연체료는 계산할 수 없어 호출하는 쪽에서 걸러야 한다
    public static long lateFeeOf(LocalDate dueAt, LocalDate returnedAt) {
        return overdueDaysOf(dueAt, returnedAt) * LATE_FEE_PER_DAY;
    }

    private static long overdueDaysOf(LocalDate dueAt, LocalDate returnedAt) {
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.LockModeType;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    @Query("select l.id as loanId, l.bookId as bookId, b.title as title, l.loanedAt as loanedAt, l.dueAt as dueAt " +
            "from LoanJpaEntity l, BookJpaEntity b " +
            "where b.id = l.bookId and l.memberId = :memberId and l.returnedAt is null " +
            "order by l.loanedAt asc, l.id asc")
    List<ActiveLoanRow> findActiveLoanRows(@Param("memberId") UUID memberId, Pageable pageable);

    @Query("select l.id as loanId, b.title as title, l.loanedAt as loanedAt, l.dueAt as dueAt, " +
            "l.returnedAt as returnedAt " +
            "from LoanJpaEntity l, BookJpaEntity b " +
            "where b.id = l.bookId and l.memberId = :memberId " +
            "order by l.loanedAt desc, l.id desc")
    List<LoanHistoryRow> findLoanHistoryRows(@Param("memberId") UUID memberId);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from LoanJpaEntity l where l.id = :id")
    Optional<LoanJpaEntity> findForUpdateById(@Param("id") UUID id);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoan;
import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoanPage;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadLoanHistoryPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort, LoadActiveLoansPort, LoadLoanHistoryPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findForUpdateById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public ActiveLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        List<ActiveLoan> items = loanJpaRepository.findActiveLoanRows(memberId, PageRequest.of(page, size))
                .stream()
                .map(row -> new ActiveLoan(row.getLoanId(), row.getBookId(), row.getTitle(),
                        row.getLoanedAt(), row.getDueAt()))
                .toList();
        return new ActiveLoanPage(items, countActiveLoansByMemberId(memberId));
    }

    @Override
    public List<LoanHistoryEntry> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findLoanHistoryRows(memberId).stream()
                .map(row -> new LoanHistoryEntry(row.getLoanId(), row.getTitle(), row.getLoanedAt(),
                        row.getDueAt(), row.getReturnedAt()))
                .toList();
    }
}
