public interface ListMemberLoanHistoryUseCase {

    // 반납한 대출과 반납하지 않은 대출을 모두 대출일 최신순으로 돌려준다
    List<LoanHistoryItem> listLoanHistory(UUID memberId);

    // 반납하지 않은 대출은 returnedAt 과 lateFee 가 null 이다
    record LoanHistoryItem(UUID loanId, String title, LocalDate loanedAt, LocalDate returnedAt, Long lateFee) {
    }
}
package com.example.lending.common;

import java.time.LocalDate;

public final class DateUtils {

    private DateUtils() {
    }

    public static LocalDate addDays(LocalDate date, int days) {
        return date.plusDays(days);
    }
}

