        String middle = loanOn(registerBook("Effective Java"), memberId, LocalDate.of(2026, 2, 20));
        mockMvc.perform(post("/loans/{loanId}/return", oldest).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-10\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/loans/{loanId}/return", middle).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-10\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].title").value("Refactoring"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").isEmpty())
                .andExpect(jsonPath("$[0].lateFee").isEmpty())
                .andExpect(jsonPath("$[1].title").value("Effective Java"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-02-20"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-10"))
