                .andExpect(jsonPath("$[1].lateFee").value(400))
                .andExpect(jsonPath("$[2].title").value("Clean Code"))
                .andExpect(jsonPath("$[2].loanedAt").value("2026-02-01"))
                .andExpect(jsonPath("$[2].returnedAt").value("2026-02-10"))
                .andExpect(jsonPath("$[2].lateFee").value(0));
    }

    @Test
    void late_return_shows_late_fee_in_history() throws Exception {
        String memberId = registerMember();
