package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadMonthlyLoanStatsPort;
import com.example.lending.application.port.out.LoadMonthlyLoanStatsPort.ReturnedLoan;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadMonthlyLoanStatsPort loadMonthlyLoanStatsPort;

    public GetMonthlyStatsService(LoadMonthlyLoanStatsPort loadMonthlyLoanStatsPort) {
        this.loadMonthlyLoanStatsPort = loadMonthlyLoanStatsPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        YearMonth yearMonth = toYearMonth(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.atEndOfMonth();

        long loanCount = loadMonthlyLoanStatsPort.countLoanedBetween(from, to);
        List<ReturnedLoan> returns = loadMonthlyLoanStatsPort.loadReturnedBetween(from, to);

        long overdueCount = 0;
        long lateFeeTotal = 0;
        for (ReturnedLoan returned : returns) {
            long lateFee = Loan.lateFeeOf(returned.dueAt(), returned.returnedAt());
            if (lateFee > 0) {
                overdueCount++;
            }
            lateFeeTotal += lateFee;
        }
        return new MonthlyStats(year, month, loanCount, returns.size(), overdueCount, lateFeeTotal);
    }

    private static YearMonth toYearMonth(int year, int month) {
        try {
            return YearMonth.of(year, month);
        } catch (DateTimeException e) {
            throw new IllegalArgumentException(e.getMessage(), e);
        }
    }
}

