package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 다른 테스트와 데이터가 겹치지 않도록 2041년을 쓴다
@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void month_without_activity_returns_all_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "12"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2041))
                .andExpect(jsonPath("$.month").value(12))
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void loans_are_counted_by_loan_date_and_returns_by_return_date() throws Exception {
        String memberId = registerMember();
        // 기한 2041-07-14, 7월 반납 → 연체 없음
        String loanBeforeJuly = loanOn(registerBook("Clean Code"), memberId, LocalDate.of(2041, 6, 30));
        // 기한 2041-07-15, 2041-07-20 반납 = 5일 연체 = 500원
        String onFirstOfJuly = loanOn(registerBook("Refactoring"), memberId, LocalDate.of(2041, 7, 1));
        // 아직 반납하지 않은 대출, 7월 대출로만 집계된다
        loanOn(registerBook("Effective Java"), memberId, LocalDate.of(2041, 7, 10));
        // 기한 2041-06-15, 2041-07-31 반납 = 46일 연체 = 4600원
        String longOverdue = loanOn(registerBook("Domain-Driven Design"), memberId, LocalDate.of(2041, 6, 1));
        // 7월 말 대출이지만 반납은 8월이라 7월 반납 건수에 들어가지 않는다
        loanOn(registerBook("Patterns of Enterprise"), memberId, LocalDate.of(2041, 7, 31));

        returnOn(loanBeforeJuly, LocalDate.of(2041, 7, 2));
        returnOn(onFirstOfJuly, LocalDate.of(2041, 7, 20));
        returnOn(longOverdue, LocalDate.of(2041, 7, 31));

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(5100));

        // 6월은 대출만 있고 반납은 7월에 일어났다
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(2))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void month_out_of_range_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "13"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "0"))
                .andExpect(status().isBadRequest());
    }

    private void returnOn(String loanId, LocalDate returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanOn(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBodyOn(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new BookBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    record LoanBodyOn(String bookId, String memberId, LocalDate loanedAt) {
    }

    record BookBody(String title) {
    }
}

